('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--3',1,'{"question":"What describes a rotation?","choices":["A turn around a fixed center","A slide by a fixed vector","A stretch along one axis","A flip across a line"],"answer":0,"explanation":""}'::jsonb,'2985d6ebb3b07764aa7210fc4ad36f28','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--4',1,'{"question":"Reflect (3, −2) across the x-axis. What is its image?","choices":["(−3, −2)","(−3, 2)","(2, 3)","(3, 2)"],"answer":3,"explanation":""}'::jsonb,'107350b5b3e2089b9bd575f1cd510344','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--5',1,'{"question":"Reflect (4, 1) across the y-axis. What is its image?","choices":["(4, −1)","(−4, −1)","(−4, 1)","(1, 4)"],"answer":2,"explanation":""}'::jsonb,'68075bd9fdd77eeb023ef241f5a5a3c7','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--6',1,'{"question":"Translate (−1, 5) by (x, y) → (x + 3, y − 2). What is its image?","choices":["(−4, 7)","(2, 3)","(2, 7)","(−4, 3)"],"answer":1,"explanation":""}'::jsonb,'cc0fbc8a9ff2f8f5646085b9343aea8e','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--7',1,'{"question":"What is a line of symmetry?","choices":["A line across which reflection maps a figure onto itself","Any line through a vertex","A line that divides a figure into equal areas only","Any diagonal of a polygon"],"answer":0,"explanation":""}'::jsonb,'d707c932d04b7b94738d24a1ce872178','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--8',1,'{"question":"Why does a scalene triangle have no line of symmetry?","choices":["Every triangle has three symmetry lines","A triangle must have a right angle to be symmetric","Symmetry requires curved sides","No reflection line matches its unequal sides and vertices"],"answer":3,"explanation":""}'::jsonb,'ef9135a6a5012e8182e8c7be2bf0c4a4','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--9',1,'{"question":"How many lines of symmetry does a square have?","choices":["2","1","4","8"],"answer":2,"explanation":""}'::jsonb,'387b07b861a3f087104dad8256d9d495','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--10',1,'{"question":"Rotate (2, 5) by 180° about the origin. What is its image?","choices":["(5, 2)","(−2, −5)","(−5, 2)","(2, −5)"],"answer":1,"explanation":""}'::jsonb,'f65efa9cb642b6b4a7a59ef583f73f63','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--11',1,'{"question":"Which rule reflects points across y = x?","choices":["(x, y) → (y, x)","(x, y) → (−x, y)","(x, y) → (x, −y)","(x, y) → (−y, −x)"],"answer":0,"explanation":""}'::jsonb,'2d05a701be1167a5b61e7e96bbb25bb5','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--12',1,'{"question":"A dilation centered at the origin has scale factor 3. Where does (2, −1) move?","choices":["(5, 2)","(2/3, −1/3)","(−6, 3)","(6, −3)"],"answer":3,"explanation":""}'::jsonb,'0deec851ea8baf7404f2442eeeabb9e5','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--13',1,'{"question":"Why is a dilation with scale factor 2 not a rigid motion?","choices":["It changes all angle measures","It removes vertices","It doubles distances between distinct points","It always reflects the figure"],"answer":2,"explanation":""}'::jsonb,'1ae30fb8e5c810ca891fbec21150d1b9','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--14',1,'{"question":"What is the smallest positive rotation that maps a regular hexagon onto itself about its center?","choices":["30°","60°","90°","120°"],"answer":1,"explanation":""}'::jsonb,'2b9d3af68d7d2289a1710708d396dc4b','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--15',1,'{"question":"How many lines of symmetry does a nonsquare rectangle have?","choices":["2","4","1","0"],"answer":0,"explanation":""}'::jsonb,'108b374de41ad629b93c51e32135bd28','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--16',1,'{"question":"A point is reflected across the y-axis twice. Where does it end?","choices":["At its opposite across the x-axis","At the origin","At twice its original distance from the axis","At its original location"],"answer":3,"explanation":""}'::jsonb,'11abf520b3d4e1584069aefb5cdaec49','official',NULL,NULL,'Transformations and Symmetry')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--17',1,'{"question":"Rotate (3, 1) by 90° counterclockwise about the origin. What is its image?","choices":["(1, −3)","(−3, −1)","(−1, 3)","(1, 3)"],"answer":2,"explanation":""}'::jsonb,'84cd809dafd40a8840521374a6500560','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--18',1,'{"question":"A design matches itself after a 120° turn, and 120° is its smallest positive matching turn. What is its rotational symmetry order?","choices":["2","3","4","6"],"answer":1,"explanation":""}'::jsonb,'2b287e7a2592e2d2be4ad9c1c39caa7a','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--19',1,'{"question":"Translate (2, 3) right 4 and up 1, then reflect across the x-axis. What is the final point?","choices":["(6, −4)","(−6, 4)","(6, 4)","(−2, −4)"],"answer":0,"explanation":""}'::jsonb,'9b96b11e0b3bb307426ec18353cbd2ca','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--transformations-and-symmetry:math--geometry--transformations-and-symmetry--20',1,'{"question":"Which operation turns a square into a nonsquare rectangle?","choices":["Reflecting across a diagonal","Rotating 45° about its center","Translating it 5 units right","Stretching only its horizontal dimension"],"answer":3,"explanation":""}'::jsonb,'09f4fe57984da6e5ee2bf205c9ff08f2','official',NULL,NULL,'Transformations and Symmetry'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--1',1,'{"question":"What is a geometric proof?","choices":["A drawing that looks convincing","A list of measurements from one example","A guess about a diagram","A logical argument based on accepted facts and justified steps"],"answer":3,"explanation":""}'::jsonb,'0d5e7736db6f6ffee2d6431d07f437ee','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--2',1,'{"question":"What is a conjecture?","choices":["A proven theorem in every case","A definition of a shape","A statement proposed from patterns that still needs justification","A calculation with no variables"],"answer":2,"explanation":""}'::jsonb,'3a4e1a23ce99cd709f1181e10fa3fab2','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--3',1,'{"question":"What is a counterexample?","choices":["One case that agrees with the claim","One valid case that disproves a universal claim","An unrelated diagram","A theorem that uses the same words"],"answer":1,"explanation":""}'::jsonb,'7ad54a9a490885ad4cabca8c318c1324','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--4',1,'{"question":"Which property supports ''if a = b and b = c, then a = c''?","choices":["The transitive property of equality","The distributive property","The commutative property of multiplication","The identity property of addition"],"answer":0,"explanation":""}'::jsonb,'39f5b109efe67cbcf4c62e064040d81e','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--5',1,'{"question":"What is given information in a proof?","choices":["Every feature that appears visually true","Only the final conclusion","Any unmeasured length in the picture","Facts stated or marked as assumptions for the problem"],"answer":3,"explanation":""}'::jsonb,'8dd875d06496771b5400b8bdaffc700f','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--6',1,'{"question":"Which fact justifies that a segment equals itself in length?","choices":["The zero-product property","The triangle inequality","The reflexive property","The parallel postulate"],"answer":2,"explanation":""}'::jsonb,'af1af5b1a9882e079e010909d0eb2e6e','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--7',1,'{"question":"What distinguishes a theorem from a conjecture?","choices":["A theorem always involves numbers","A theorem has a proof under its stated assumptions","A conjecture is always false","A theorem cannot have conditions"],"answer":1,"explanation":""}'::jsonb,'1a80a8d407176e12b8a34ffab2cbce5b','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--8',1,'{"question":"Why is measuring one drawn triangle insufficient to prove a claim about all triangles?","choices":["One example does not establish every possible case","Triangle measurements never use degrees","A drawing cannot show a triangle","Every universal claim is false"],"answer":0,"explanation":""}'::jsonb,'81376392cf898ad9b24be5ba323fc19d','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--9',1,'{"question":"What is the converse of ''If a figure is a square, then it is a rectangle''?","choices":["If a figure is not a square, then it is not a rectangle","If a figure is a square, then it is not a rectangle","Every rectangle has equal sides","If a figure is a rectangle, then it is a square"],"answer":3,"explanation":""}'::jsonb,'4c67670eca735712e762310428f16ae1','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--10',1,'{"question":"Which figure disproves ''Every rectangle is a square''?","choices":["A square with side 4","A rectangle with all sides 6","A rectangle with sides 3 and 5","A circle with radius 3"],"answer":2,"explanation":""}'::jsonb,'116cc21dae8330eb9789cc479a8c17e1','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--11',1,'{"question":"Which statement is an example of deductive reasoning?","choices":["Several measured triangles suggest an angle-sum pattern","A triangle''s angles total 180°, so the third angle is 70° when the others are 50° and 60°","A shape looks symmetric, so it probably is","Three examples make every quadrilateral a rectangle"],"answer":1,"explanation":""}'::jsonb,'b7c0b24f6f3099ff6c6e14627d79f7a0','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--12',1,'{"question":"Why should a diagram not be assumed to be drawn to scale?","choices":["Visual appearance may not match the stated measurements","Every diagram has incorrect labels","Angles cannot be shown in drawings","Only circles can be drawn accurately"],"answer":0,"explanation":""}'::jsonb,'1f9f9db28afa3e5eee6a73346e8fb6d9','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--13',1,'{"question":"If AB = CD, what justifies replacing AB with CD in an equation?","choices":["Multiplying both sides by zero","The converse of every theorem","Rounding to the nearest integer","Substitution"],"answer":3,"explanation":""}'::jsonb,'d3cf63d8e2f6d483a4b90b4a678b28a2','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--14',1,'{"question":"Which condition is needed before using corresponding-angle equality to prove two lines parallel?","choices":["The lines must already be labeled parallel","The angles must both be acute","The angles must be corresponding angles formed by the same transversal","The transversal must be horizontal"],"answer":2,"explanation":""}'::jsonb,'6d6532256a90f1a7a0111c02ffe540b9','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--15',1,'{"question":"Which statement uses inductive reasoning?","choices":["Applying an established theorem to a specified triangle","Observing several cases and proposing a general pattern","Using equality substitution in a proof","Deriving a conclusion from given premises"],"answer":1,"explanation":""}'::jsonb,'3e49213cdd92a9ce24e0fda431535228','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--16',1,'{"question":"A student proves two triangles congruent and then concludes their corresponding sides are equal. What supports that final step?","choices":["Corresponding parts of congruent triangles are equal","All triangles have equal sides","Every pair of angles is supplementary","Equal perimeter alone proves congruence"],"answer":0,"explanation":""}'::jsonb,'f4adb876877751e0bdaa3d4844bba163','official',NULL,NULL,'Geometric Proof and Reasoning'),
