('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--18',1,'{"question":"If a proof needs x = 4 but its steps show only x² = 16, what remains to be justified?","choices":["Why 16 is positive","Why x must equal 16","Why x = −4 is excluded","Why squaring changes 4 to 8"],"answer":2,"explanation":""}'::jsonb,'e10ce98bfc26ed78b8a4e36a8ec81a9c','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--19',1,'{"question":"Why is the converse of a true statement not automatically true?","choices":["A true statement has no hypothesis","Reversing the hypothesis and conclusion creates a different claim","Every converse is false","A conclusion cannot be used as a hypothesis"],"answer":1,"explanation":""}'::jsonb,'92f57f48038831cadb60b40491c5361d','official',NULL,NULL,'Geometric Proof and Reasoning'),
('original:math--geometry--geometric-proof-and-reasoning:math--geometry--geometric-proof-and-reasoning--20',1,'{"question":"A student assumes the desired conclusion to justify an earlier step. What is the main problem?","choices":["The argument is circular","The argument has too many diagrams","The argument uses exact values","The argument includes definitions"],"answer":0,"explanation":""}'::jsonb,'69a438b250dc054b6e954760ff941de3','official',NULL,NULL,'Geometric Proof and Reasoning'),
