('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--2',1,'{"question":"Which transformation is a rigid motion?","choices":["A rotation","A dilation with scale factor 3","A horizontal stretch by 2","A vertical compression by 1/2"],"answer":0,"explanation":""}'::jsonb,'56a9e05ce9a720bea86df4ebfeecfb1c','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--3',1,'{"question":"How can congruent figures be related through transformations?","choices":["Any enlargement maps one onto the other","Only a change in area can match them","Their corresponding angles must change","A sequence of rigid motions maps one exactly onto the other"],"answer":3,"explanation":""}'::jsonb,'82f69b7affd41a35841a347c9f02d82f','official',NULL,NULL,'Congruence and Rigid Motions'),
