('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--5',1,'{"question":"Which dilation preserves all distances?","choices":["Scale factor 2","Scale factor 1","Scale factor 1/2","Scale factor 3"],"answer":1,"explanation":""}'::jsonb,'89ea95a8fa2305f0c2576f7079e65c01','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--6',1,'{"question":"What is orientation in the context of a labeled polygon?","choices":["The clockwise or counterclockwise order of its vertices","Its total perimeter","Its distance from the origin","Its number of diagonal segments"],"answer":0,"explanation":""}'::jsonb,'05931436012e592a77bbe030895ee482','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--7',1,'{"question":"Which single rigid motion reverses orientation?","choices":["A translation","A rotation by 90°","A rotation by 180°","A reflection"],"answer":3,"explanation":""}'::jsonb,'839bf5f7716a7284d7b1d4412505691c','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--8',1,'{"question":"Why can two congruent figures have different coordinates?","choices":["Coordinates determine only area","Congruence requires identical coordinates","Rigid motions may change position while preserving size and shape","Congruence permits different side lengths"],"answer":2,"explanation":""}'::jsonb,'c95af98d902de9ba6bccd54b1d0af695','official',NULL,NULL,'Congruence and Rigid Motions'),
