('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--10',1,'{"question":"What happens to a triangle''s area under a translation?","choices":["It stays equal","It doubles","It becomes zero","It changes by the translation distance"],"answer":0,"explanation":""}'::jsonb,'269ac5054f7bfcc9a723a586b572bec4','official',NULL,NULL,'Congruence and Rigid Motions'),
