('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--12',1,'{"question":"Why is matching only area insufficient to prove congruence?","choices":["Congruent figures always have unequal areas","Area is undefined for polygons","Different shapes can have equal areas","Equal areas force equal side lengths"],"answer":2,"explanation":""}'::jsonb,'e000004e4174c2a24ed8e7a707d52c61','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--13',1,'{"question":"Which comparison best supports congruence after a transformation?","choices":["Only the figures'' centers are equally high","Corresponding lengths and angles are unchanged","The figures have the same number of vertices","Both figures lie in the same quadrant"],"answer":1,"explanation":""}'::jsonb,'f3e2bbf17ed1a8915f6c5a27424ef4ff','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--14',1,'{"question":"A figure is reflected and then translated. Is the final image congruent to the original?","choices":["Yes, both steps preserve distances and angles","No, any two-step transformation changes size","Only if the translation distance is zero","Only if the figure is a circle"],"answer":0,"explanation":""}'::jsonb,'431e0514af2af4b8cc1de9bda9ef6720','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--15',1,'{"question":"What happens to perimeter under any sequence of rigid motions?","choices":["It changes by the number of steps","It doubles after a reflection","It depends on the rotation angle","It is unchanged"],"answer":3,"explanation":""}'::jsonb,'dece1093d97ab35b63dd88f7cadfd517','official',NULL,NULL,'Congruence and Rigid Motions'),
('original:math--geometry--congruence-and-rigid-motions:math--geometry--congruence-and-rigid-motions--16',1,'{"question":"Two triangles have equal corresponding sides but opposite vertex orientation. Which type of motion may be needed to match their labeled vertices?","choices":["A dilation by 2","A stretch in one direction","A reflection as part of the matching sequence","A change to one side length"],"answer":2,"explanation":""}'::jsonb,'e4476acf21b229d1cdf804deb1b1f8b0','official',NULL,NULL,'Congruence and Rigid Motions'),
