('original:math--statistics-probability--normal-distributions:math--statistics-probability--normal-distributions--20',1,'{"question":"A normal model with mean 10 and standard deviation 2 is used for heights. Which finding suggests the model should be reconsidered?","choices":["Some observations are above 10","The sample mean is close to 10","The standard deviation is positive","The observed histogram is strongly right-skewed"],"answer":3,"explanation":""}'::jsonb,'ee8c6c52e70e4d76e38efb981bfc13cf','official',NULL,NULL,'Normal Distributions'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--1',1,'{"question":"How is standard deviation related to variance?","choices":["It is the square of variance","It is half the variance","It is the reciprocal of variance","It is the nonnegative square root of variance"],"answer":3,"explanation":""}'::jsonb,'f23486503f40c6c20dfc126b025a56e4','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--2',1,'{"question":"Which formula gives a z-score for value x, mean μ, and positive standard deviation σ?","choices":["z = (x + μ)/σ","z = xσ − μ","z = (x − μ)/σ","z = μ/x"],"answer":2,"explanation":""}'::jsonb,'88de8f265eab9eb49cfc100fec1d2995','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--3',1,'{"question":"What does a z-score of 0 mean?","choices":["The value equals zero","The value equals the mean","The distribution has no spread","The value is the maximum"],"answer":1,"explanation":""}'::jsonb,'382a0338843c2ce343cd2bca3db6eb01','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--4',1,'{"question":"What does a negative z-score indicate?","choices":["The value lies below the mean","The original value must be negative","The standard deviation is negative","The value lies above the mean"],"answer":0,"explanation":""}'::jsonb,'6097c808451b4ee357793a98dc080f2d','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--5',1,'{"question":"Can standard deviation be negative?","choices":["Yes; when the mean is negative","Yes; when all values are below zero","Only for a sample","No; it is nonnegative"],"answer":3,"explanation":""}'::jsonb,'13a8235abfe0cb275bfdfaf0645ce5a1','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--6',1,'{"question":"What units does standard deviation use?","choices":["Squared original units","No units in every case","The same units as the original values","The reciprocal of the original units"],"answer":2,"explanation":""}'::jsonb,'ed72f13ad1f4a41a1657d7c464194f24','official',NULL,NULL,'Standard Deviation and Z-Scores'),
