('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--9',1,'{"question":"A value is 40, the mean is 50, and the standard deviation is 10. What is its z-score?","choices":["1","−10","4","−1"],"answer":3,"explanation":""}'::jsonb,'3873ffc4585fee6bf7086dfc8d6817cf','official',NULL,NULL,'Standard Deviation and Z-Scores'),
('original:math--statistics-probability--standard-deviation-and-z-scores:math--statistics-probability--standard-deviation-and-z-scores--10',1,'{"question":"Why do z-scores help compare measurements on different scales?","choices":["They make every original value identical","They remove all distribution differences","They express distances from means in standard-deviation units","They guarantee equal percentiles for differently shaped distributions"],"answer":2,"explanation":""}'::jsonb,'bc43f3a6ff594421c1d3f2e821f1ac63','official',NULL,NULL,'Standard Deviation and Z-Scores'),
