('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--9',1,'{"question":"Students are randomly assigned to two study methods before taking the same test. What is the treatment variable?","choices":["The test score","The students'' names","The assigned study method","The number of test questions"],"answer":2,"explanation":""}'::jsonb,'af6a86887e13c056bb911b7373a3ab64','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--10',1,'{"question":"In an experiment comparing two study methods, why should both groups take the same test under similar conditions?","choices":["To ensure every student earns the same score","To avoid differences in testing conditions confounding the comparison","To eliminate the need for assignment","To guarantee the new method works"],"answer":1,"explanation":""}'::jsonb,'b568c27929ef7967b1c2350ca8dc14f6','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--11',1,'{"question":"What is the purpose of blinding participants to treatment labels when practical?","choices":["To reduce expectation-related changes in behavior or reporting","To prevent researchers from measuring outcomes","To eliminate all random variation","To make the sample larger"],"answer":0,"explanation":""}'::jsonb,'3d2359166737df5ac6713a5eda5c7a09','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--12',1,'{"question":"What is a randomized block design?","choices":["Assigning every member of a group the same treatment without randomization","Selecting only units with identical outcomes","Discarding groups that disagree with the hypothesis","Grouping similar units first, then randomizing treatments within each group"],"answer":3,"explanation":""}'::jsonb,'8e4eea818e90a0bf7df790c60474588f','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--13',1,'{"question":"Why can matched-pairs designs be useful?","choices":["They guarantee that every pair has the same response","They avoid all random assignment","They compare treatments within the same unit or closely matched pairs","They require twice as many distinct treatments as units"],"answer":2,"explanation":""}'::jsonb,'4b62b414bb2ce2f24364b24034cf013a','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--14',1,'{"question":"Which design most directly supports causal inference when well conducted?","choices":["A voluntary opinion poll","A randomized controlled experiment","A comparison of unrelated historical averages","A single observed success story"],"answer":1,"explanation":""}'::jsonb,'e37effed9c21a64d58a19cbba4aad5db','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--15',1,'{"question":"Why should a study''s response measure be defined before results are examined?","choices":["It reduces selective choice of outcomes after seeing data","It forces every hypothesis to be accepted","It makes measurement error impossible","It removes the need for a comparison group"],"answer":0,"explanation":""}'::jsonb,'13eed02777838c616629ca8740e8749f','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--16',1,'{"question":"A school gives a new program only to already high-achieving students, then compares them with others. What is the key concern?","choices":["Random assignment made the groups too similar","The response variable cannot be measured","The sample is too large to analyze","Prior achievement is confounded with program assignment"],"answer":3,"explanation":""}'::jsonb,'901006864f9d9064a595487b342fce42','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--17',1,'{"question":"A coin flip assigns each participant to one of two treatments. Which issue does this address most directly?","choices":["Population coverage bias","Every measurement error","Treatment allocation bias","The need for an outcome variable"],"answer":2,"explanation":""}'::jsonb,'491d7f4986b900c1a0af19096dc957e4','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--18',1,'{"question":"A study randomly samples residents but lets each choose a treatment. Which claim needs caution?","choices":["A description of the sampled residents'' choices","A causal claim, because treatment was not randomly assigned","A count of the residents in the sample","A statement that a random sample was used"],"answer":1,"explanation":""}'::jsonb,'c35dc830c8d497cff84a29f43ade9ad2','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--19',1,'{"question":"In a crossover study, every participant receives both conditions. Why might their order be randomized?","choices":["Order or carryover effects could influence results","Random order makes the two conditions identical","Every participant must receive only one condition","Random order removes the need to measure responses"],"answer":0,"explanation":""}'::jsonb,'d0947dba6d5118a2c23fcd84bdcfac52','official',NULL,NULL,'Experimental Design and Causation'),
('original:math--statistics-probability--experimental-design-and-causation:math--statistics-probability--experimental-design-and-causation--20',1,'{"question":"A well-conducted randomized experiment finds different average outcomes between treatments. What should be assessed before concluding the treatment has an effect?","choices":["Whether the larger average automatically proves causation without uncertainty","Whether every participant showed an identical response","Whether the treatment-group mean equals the population mean","Whether the difference is larger than expected from chance variation"],"answer":3,"explanation":""}'::jsonb,'2efc4916c9db518b62c94e0deb5a88b0','official',NULL,NULL,'Experimental Design and Causation'),
